// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        // No inputs to restrict; the reference works for any bytes32
        // Drive the contract through the public surface leading to assertionDisputedCallback
        // Note: assertionDisputedCallback is called by the optimisticAsserter; we are the asserter in setUp
        // To trigger it we need to call it directly but it's restricted; we can't call it directly because it's onlyOptimisticAsserter
        // However the property we want to test is about getAssertionPolicy, which is public and can be called directly
        // The difference manifests in getAssertionPolicy, which is the function that changed.
        // So we just call getAssertionPolicy and check the value.
        C.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        assertTrue(!policy.arbitrateViaEscalationManager);
    }
}

